insert into ideas (id, category, title, hook, image, video, kind, model, aspect, duration, resolution, motion, prompt, variaciones, fuente, tendencia, oculta, orden) values
  ('maquina-cascos', 'Negocios y máquinas', 'Máquina lava cascos en un mall', 'El negocio que trabaja solo: muéstralo funcionando en un lugar real.', '/showcase/idea-maquina-cascos.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Video de producto de una máquina de autoservicio para lavar cascos: un quiosco fijo del tamaño de un cajero automático, de pie contra una columna en un centro comercial de Lima, cuerpo negro brillante con luces LED azules, pantalla táctil y una puerta de vidrio. Dentro de la cámara de vidrio, un casco de moto vacío gira mientras lo limpian con luz azul y vapor. Un joven sin casco, de pie al lado, mira la pantalla y sonríe. No hay motos ni motociclistas en la escena. Voz masculina peruana entusiasta dice: «Este negocio cobra mientras tú duermes». Sonido ambiente de centro comercial. Sin logos ni marcas.', '[]'::jsonb, null, false, false, 1),
  ('selladora-latas', 'Negocios y máquinas', 'Selladora de latas en feria', 'Bebidas en lata al momento: el clip que hace preguntar «¿dónde la compro?».', '/showcase/idea-selladora.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Una máquina selladora de latas de acero y negro con bordes LED azules en un mercado de comida de noche. Un vendedor pone un vaso de chicha morada, la máquina baja la tapa y sella la lata con un clic. La lata sale brillante y la entrega a un cliente. Sonido de la máquina sellando y murmullo del mercado. Sin logos.', '[]'::jsonb, null, false, false, 2),
  ('antes-despues', 'Negocios y máquinas', 'Antes y después', 'El formato que más comparte la gente: la transformación en una sola imagen.', '/showcase/idea-antes-despues.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Imagen vertical dividida en dos: a la izquierda con la palabra ANTES un casco de moto sucio y gastado, a la derecha con la palabra DESPUÉS el mismo casco limpio y brillante como nuevo. Fondo blanco de estudio, etiquetas grandes en negro.', '[]'::jsonb, null, false, false, 3),
  ('vending-flores', 'Negocios y máquinas', 'Máquina de flores en el metro', 'Un negocio de autoservicio que la gente graba y comparte.', '/showcase/idea-vending-flores.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Una máquina expendedora de flores con vitrina de vidrio iluminada en una estación del Metro de Lima, ramos de rosas y girasoles en cada casillero. Una joven elige un ramo en la pantalla táctil, la puerta se abre y saca las flores sonriendo. Sonido ambiente de estación y un pitido de la máquina. Sin logos.', '[]'::jsonb, null, false, false, 4),
  ('impresora-3d', 'Negocios y máquinas', 'Impresora 3D fabricando', 'Hipnótico: ver cómo nace un producto capa por capa.', '/showcase/idea-impresora-3d.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Primer plano macro de una impresora 3D trabajando de noche en un taller, la boquilla deposita filamento azul brillante capa por capa formando un llavero. Luz LED blanca y reflejos azules, la cámara se acerca lento. Zumbido suave de los motores, sin voz.', '[]'::jsonb, null, false, false, 5),
  ('food-truck', 'Negocios y máquinas', 'Food truck con tu marca', 'Presenta tu carrito o food truck antes de tenerlo.', '/showcase/idea-food-truck.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto realista vertical de un food truck moderno de color amarillo estacionado en un parque de Lima al atardecer, con el letrero grande SALCHIPAPAS EXPRESS en letras negras sobre el techo, clientes haciendo cola, luces cálidas colgadas.', '[]'::jsonb, null, false, false, 6),
  ('brainrot-llama', 'Brainrot', 'Llamalicuadora Chichamorada', 'Animales y objetos peruanos fusionados, con su nombre cantado.', '/showcase/brainrot-llama.jpg', '/showcase/brainrot-llama.mp4', 'video', 'ltx-25', '9:16', 5, '720p', null, 'Render 3D hiperrealista y absurdo estilo meme brainrot: una llama peruana cuyo cuerpo es una licuadora gigante llena de chicha morada, girando y salpicando en la Plaza de Armas del Cusco. Una voz masculina dramática canta: «¡Llamalicuadora Chichamorada!». Sonido de licuadora. Sin subtítulos.', '[]'::jsonb, null, false, false, 7),
  ('brainrot-cuy', 'Brainrot', 'Cuyastronauto Mototaxino', 'Inventa tu propio personaje: un animal + un objeto + un lugar.', '/showcase/brainrot-cuy.jpg', '/showcase/brainrot-cuy.mp4', 'video', 'ltx-25', '9:16', 5, '720p', null, 'Render 3D hiperrealista y absurdo estilo meme brainrot: un cuy astronauta con traje plateado maneja un mototaxi volador sobre los cerros del Cusco al atardecer y saluda a la cámara. Voz épica grita: «¡Cuyastronauto Mototaxino!». Ruido de motor y viento. Sin subtítulos.', '[]'::jsonb, null, false, false, 8),
  ('brainrot-pollo', 'Brainrot', 'Pollerina Marinerina', 'Comida que baila: funciona en TikTok y Reels.', '/showcase/brainrot-pollo.jpg', '/showcase/brainrot-pollo.mp4', 'video', 'ltx-25', '9:16', 5, '720p', null, 'Render 3D hiperrealista y absurdo estilo meme brainrot: un pollo a la brasa dorado con piernas de bailarina baila marinera con un pañuelo blanco en un escenario de madera. Voz teatral canta: «¡Pollerina Marinerina!». Zapateo y guitarra festiva. Sin subtítulos.', '[]'::jsonb, null, false, false, 9),
  ('brainrot-papa', 'Brainrot', 'Papasito Mototaxito', 'Un alimento peruano + un vehículo de barrio: combinación ganadora.', '/showcase/brainrot-papa.jpg', '/showcase/brainrot-papa.mp4', 'video', 'ltx-25', '9:16', 5, '720p', null, 'Render 3D hiperrealista y absurdo estilo meme brainrot: una papa amarilla gigante con lentes de sol maneja una mototaxi roja por una calle de Lima tocando la bocina. Voz masculina exagerada canta: «¡Papasito Mototaxito!». Sonido de motor y bocina. Sin subtítulos.', '[]'::jsonb, null, false, false, 10),
  ('brainrot-pez', 'Brainrot', 'Pescadito Taxidito', 'Personajes absurdos en lugares que todos reconocen.', '/showcase/brainrot-pez.jpg', '/showcase/brainrot-pez.mp4', 'video', 'ltx-25', '9:16', 5, '720p', null, 'Render 3D hiperrealista y absurdo estilo meme brainrot: un pez gigante con cuerpo de taxi amarillo avanza entre el tráfico de la Vía Expresa de Lima moviendo la cola. Voz dramática grita: «¡Pescadito Taxidito!». Bocinas y tráfico. Sin subtítulos.', '[]'::jsonb, null, false, false, 11),
  ('brainrot-alpaca', 'Brainrot', 'Alpacachino Cafetero', 'Animal andino + máquina de café: el meme que se hace solo.', '/showcase/idea-brainrot-alpaca.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', null, 'Render 3D hiperrealista y absurdo estilo meme brainrot: una alpaca blanca cuyo cuerpo es una máquina de café espresso plateada echa vapor por las orejas y sirve un capuchino en una cafetería de Arequipa. Voz cantada y exagerada: «¡Alpacachino Cafetero!». Sonido de vapor y taza. Sin subtítulos.', '[]'::jsonb, null, false, false, 12),
  ('frutinovela', 'Historias', 'Frutinovela: el mensaje', 'Capítulos cortos con final en suspenso; el mismo personaje en cada escena.', '/showcase/fresa-llorando.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Una fresa con rasgos humanos, ojos grandes, vestido rojo y aretes dorados, llorando mientras lee un mensaje en el celular, sentada en la cocina de su casa. Animación 3D cinematográfica, iluminación dramática de telenovela. Sin texto.', '[]'::jsonb, null, false, false, 13),
  ('miniserie-taxi', 'Historias', 'Miniserie: el sobre', 'Gancho en el primer segundo y corte justo en la reacción.', '/showcase/miniserie-taxi.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'acercamiento', 'Primer plano del rostro de un taxista de 40 años, de noche, visto desde el asiento del copiloto. Detrás de él solo se ve la ventana lateral oscura, cubierta de gotas de lluvia. Mira un sobre blanco liso que sostiene en la mano y su cara se congela. Dice en voz baja en español latino: "¿Cómo sabían que era yo?". Sonido constante de lluvia sobre el techo del auto.', '[]'::jsonb, null, false, false, 14),
  ('fabula-zorro', 'Historias', 'Fábula con narrador', 'Un animal sabio que cuenta lecciones de dinero y trabajo.', '/showcase/fabula-zorro.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Ilustración cinematográfica vintage en tonos sepia y dorado: un zorro sabio con traje de tweed sentado en un sillón de cuero junto a una lámpara de bronce, leyendo un libro de cuentas. Luz cálida de lámpara, textura de papel antiguo. Sin texto.', '[]'::jsonb, null, false, false, 15),
  ('frutinovela-traicion', 'Historias', 'Frutinovela: la traición', 'Capítulo 2: celos, miradas y un final que deja con ganas de más.', '/showcase/idea-frutinovela-traicion.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Animación 3D estilo Pixar: personajes que son frutas con cara, brazos y piernas. Un mango amarillo con bigote y camisa espía detrás de una cortina roja a un plátano y una fresa con ojos grandes que conversan en una sala lujosa. Iluminación dramática de telenovela. Sin humanos, sin texto.', '[]'::jsonb, null, false, false, 16),
  ('terror-pasillo', 'Historias', 'Terror en 8 segundos', 'Microhistorias de miedo: tensión y corte en el peor momento.', '/showcase/idea-terror-pasillo.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'acercamiento', 'Plano cinematográfico de noche en el pasillo de un edificio antiguo del Centro de Lima, una luz fluorescente parpadea. Al fondo una puerta se abre sola muy despacio. Una voz susurra: «No mires atrás». Zumbido de la luz y crujido de la puerta. Sin subtítulos.', '[]'::jsonb, null, false, false, 17),
  ('cuento-abuela', 'Historias', 'Cuento animado', 'Historias para niños con un personaje tierno que vuelve en cada video.', '/showcase/idea-cuento-abuela.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Animación 3D estilo película familiar: una abuelita andina con chompa de colores y trenzas canosas le cuenta un cuento a dos niños sentados junto a una chimenea en una casa de adobe, luz cálida del fuego, expresiones tiernas. Sin texto.', '[]'::jsonb, null, false, false, 18),
  ('influencer-cafe', 'Influencers IA', 'Creadora hablando a cámara', 'Videos tipo UGC con voz en español para presentar productos.', '/showcase/ltx-cafe.jpg', '/showcase/ltx-cafe.mp4', 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Video selfie grabado por ella misma con el brazo extendido: una joven peruana en una cafetería pequeña de Miraflores con paredes de ladrillo y plantas mira directo al lente, sonríe y dice con voz alegre: «Hoy les traigo el mejor café de Miraflores». No se ve ningún celular ni sus manos en el cuadro. Se escucha el murmullo de la cafetería y una taza sobre la mesa. Luz cálida de mañana, leve movimiento de cámara en mano.', '[]'::jsonb, null, false, false, 19),
  ('modelo-producto', 'Influencers IA', 'Modelo con tu producto', 'Sube la foto real de tu producto y ponla en manos de tu creadora virtual.', '/showcase/modelo-ia.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto realista de celular de una creadora de contenido latina en un departamento luminoso de Miraflores, sosteniendo el producto de la imagen de referencia junto a su cara y sonriendo a la cámara. Luz natural de ventana, piel real.', '[]'::jsonb, null, false, false, 20),
  ('resena-auto', 'Influencers IA', 'Reseña desde el auto', 'El formato UGC que más convierte: alguien real recomendando.', '/showcase/idea-resena-auto.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Un joven peruano sentado en el asiento del conductor de su auto estacionado mira a la cámara del celular y dice con voz natural: «Lo probé una semana y no lo cambio por nada». Luz natural de día por la ventana, cámara en mano, sonido ambiente de calle.', '[]'::jsonb, null, false, false, 21),
  ('viajera-cusco', 'Influencers IA', 'Viajera en Cusco', 'Tu influencer virtual de viajes, siempre con la misma cara.', '/showcase/idea-viajera-cusco.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto realista estilo selfie de una viajera latina de 25 años con sombrero y mochila sonriendo en un balcón con vista a la Plaza de Armas del Cusco, cielo azul, luz de mañana, piel real, foto de celular.', '[]'::jsonb, null, false, false, 22),
  ('podcast-ia', 'Influencers IA', 'Podcast con invitado IA', 'Clips de podcast que parecen grabados en estudio.', '/showcase/idea-podcast-ia.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Estudio de podcast con luz cálida y paneles acústicos: un hombre con audífonos habla a un micrófono y dice: «Nadie te cuenta esto cuando empiezas un negocio». Al frente su invitada asiente. Sonido de estudio limpio, cámara fija.', '[]'::jsonb, null, false, false, 23),
  ('producto-estudio', 'Productos y anuncios', 'Foto de estudio de producto', 'Luz, fondo y gotas de agua sin alquilar un estudio.', '/showcase/producto-serum.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto publicitaria de alta gama de un frasco de sérum de vidrio ámbar sobre roca volcánica negra mojada, gotas de agua, luz lateral dramática, fondo turquesa desenfocado, fotografía comercial.', '[]'::jsonb, null, false, false, 24),
  ('unboxing', 'Productos y anuncios', 'Unboxing', 'Manos abriendo la caja: el formato clásico que vende.', '/showcase/idea-unboxing.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Unos manos abren lentamente una caja negra premium sobre un escritorio de madera y aparece un reloj inteligente con la pantalla encendida. Luz suave de ventana, papel de seda, sonido de la caja abriéndose. Video realista de celular, sin logos.', '[]'::jsonb, null, false, false, 25),
  ('afiche-texto', 'Productos y anuncios', 'Afiche con tu marca', 'El nombre de tu negocio escrito perfecto dentro de la imagen.', '/showcase/frutilandia.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Póster vertical de una heladería llamada FRUTILANDIA, letras grandes rosadas arriba, helados de fresa y mango en primer plano, estilo fotografía publicitaria.', '[]'::jsonb, null, false, false, 26),
  ('zapatilla-flotando', 'Productos y anuncios', 'Producto flotando', 'El clásico anuncio de marca grande, para tu producto.', '/showcase/idea-zapatilla-flotando.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'orbita', 'Una zapatilla deportiva blanca flota y gira lentamente en el aire sobre un fondo azul eléctrico, salpicaduras de agua congeladas a su alrededor, luz de estudio dramática, la cámara orbita alrededor. Música electrónica suave, sin voz. Sin logos.', '[]'::jsonb, null, false, false, 27),
  ('oferta-flash', 'Productos y anuncios', 'Oferta flash', 'Promos que se leen en un segundo: precio grande y urgencia.', '/showcase/idea-oferta-flash.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche publicitario vertical con fondo rojo intenso, texto grande blanco arriba que dice OFERTA FLASH, abajo en amarillo 50% OFF SOLO HOY, en el centro unos audífonos inalámbricos negros con destellos, estilo anuncio de tienda moderna.', '[]'::jsonb, null, false, false, 28),
  ('mockup-app', 'Productos y anuncios', 'Tu app en un celular', 'Muestra tu web o app en manos de un cliente.', '/showcase/idea-mockup-app.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto realista de una mano sosteniendo un smartphone moderno con la pantalla encendida mostrando una app de compras colorida, fondo de oficina desenfocado con luz natural, enfoque en el celular, fotografía de producto.', '[]'::jsonb, null, false, false, 29),
  ('ceviche', 'Comida', 'Plato del día', 'Comida que se ve irresistible, con el texto de la promo.', '/showcase/idea-ceviche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto publicitaria vertical de un ceviche peruano fresco en un bowl de cerámica con cebolla roja, camote y choclo, limones, fondo oscuro con un solo foco cálido, vapor y gotas, texto grande blanco arriba que dice CEVICHE DEL DÍA.', '[]'::jsonb, null, false, false, 30),
  ('chef-flambeado', 'Comida', 'Chef en acción', 'Fuego, chispas y sonido: el clip que detiene el scroll.', '/showcase/idea-chef.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Un chef con uniforme negro flambea una sartén en la cocina oscura de un restaurante, grandes llamas y chispas, luz naranja dramática. Sonido del fuego y la sartén. Cinematográfico y realista.', '[]'::jsonb, null, false, false, 31),
  ('hamburguesa-lenta', 'Comida', 'Hamburguesa en cámara lenta', 'Queso derritiéndose y vapor: hambre instantánea.', '/showcase/idea-hamburguesa-lenta.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Cámara lenta de una hamburguesa doble con queso cheddar derritiéndose, la tapa de pan cae encima y salpica salsa, vapor saliendo, fondo negro con luz cálida lateral. Sonido de la plancha chisporroteando, sin voz.', '[]'::jsonb, null, false, false, 32),
  ('picarones', 'Comida', 'Picarones con miel', 'Comida típica en primer plano: el orgullo que se comparte.', '/showcase/idea-picarones.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Primer plano de una señora friendo picarones dorados en una paila de aceite en un puesto callejero de Lima de noche, luego los sirve en un plato y les echa miel de chancaca brillante. Sonido del aceite y murmullo de la calle. Sin texto.', '[]'::jsonb, null, false, false, 33),
  ('limonada-frozen', 'Comida', 'Bebida del verano', 'Hielo, gotas y color: la foto que vende bebidas.', '/showcase/idea-limonada-frozen.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto publicitaria vertical de una limonada frozen de maracuyá en un vaso alto con hielo, gotas de condensación, rodaja de limón y hojas de menta, fondo amarillo soleado, texto grande blanco arriba que dice REFRESCATE.', '[]'::jsonb, null, false, false, 34),
  ('depa-vista-mar', 'Inmobiliaria', 'Departamento con vista al mar', 'Recorridos que venden la sensación de vivir ahí.', '/showcase/idea-depa.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'paneo', 'Recorrido lento por la sala de un departamento moderno de lujo en Miraflores con ventanales de piso a techo frente al océano Pacífico al atardecer, muebles minimalistas y luces cálidas. Música suave de piano, sin voz.', '[]'::jsonb, null, false, false, 35),
  ('casa-playa', 'Inmobiliaria', 'Casa de playa desde el aire', 'El dron que vende la casa antes de la visita.', '/showcase/idea-casa-playa.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'alejamiento', 'Toma aérea cinematográfica de una casa de playa moderna blanca con piscina frente al mar en el sur de Lima al atardecer, la cámara se aleja revelando la playa y las olas. Sonido de olas y música suave, sin voz.', '[]'::jsonb, null, false, false, 36),
  ('se-alquila', 'Inmobiliaria', 'Anuncio de alquiler', 'Foto del espacio + texto claro: listo para Marketplace.', '/showcase/idea-se-alquila.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto realista vertical de una oficina moderna vacía con ventanales y vista a la ciudad de Lima, piso de madera y luz natural, con una franja azul abajo que dice en letras blancas grandes SE ALQUILA OFICINA.', '[]'::jsonb, null, false, false, 37),
  ('granja-iphones', 'Tecnología y granjas', 'Caja con decenas de iPhones', 'Plano cercano, de noche, con luces azules: el estilo de los virales de granjas.', '/showcase/ltx-granja.jpg', '/showcase/ltx-granja.mp4', 'video', 'ltx-25', '9:16', 8, '720p', 'acercamiento', 'Una caja de metal negra abierta sobre un escritorio de madera, llena de iPhones encendidos de pie en filas, cada uno con un cable USB-C en el puerto inferior. La cámara se acerca muy lento; las pantallas cambian de video y los LED azules parpadean. Detrás, un monitor con un mosaico de videos y luz morada. Zumbido de ventiladores y notificaciones suaves, sin voz.', '[]'::jsonb, null, false, false, 38),
  ('mano-iphone', 'Tecnología y granjas', 'Mano sacando un iPhone', 'El plano que más vistas trae: primer plano con mano real.', '/showcase/idea-mano-iphone.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Primer plano de una mano que saca un iPhone encendido de una caja negra llena de iPhones en filas con cables USB-C conectados en el puerto inferior, de noche, luces LED azules y cian. Zumbido de ventiladores y notificaciones suaves, sin voz.', '[]'::jsonb, null, false, false, 39),
  ('estudio-40-iphones', 'Tecnología y granjas', 'Estudio con 40 iPhones', 'La escala impresiona: decenas de pantallas trabajando a la vez.', '/showcase/idea-estudio-40-iphones.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'paneo', 'Paneo lento por un estudio oscuro con una pared de 40 iPhones montados en soportes, todos encendidos mostrando videos distintos, cables USB-C ordenados, luz azul y cian. Zumbido de ventiladores, sin voz.', '[]'::jsonb, null, false, false, 40),
  ('setup-creador', 'Tecnología y granjas', 'Setup de creador', 'El escritorio soñado para hablar de productividad o tecnología.', '/showcase/idea-setup-creador.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto realista de un escritorio de creador de contenido de noche con tres monitores, teclado mecánico iluminado, micrófono en brazo, luces LED moradas y azules detrás, una ventana con la ciudad de noche. Sin texto.', '[]'::jsonb, null, false, false, 41),
  ('emprendedor-amanecer', 'Motivación y paisajes', 'Emprendedor al amanecer', 'El fondo perfecto para tu frase motivacional.', '/showcase/idea-motivacion.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'orbita', 'Un joven emprendedor peruano de pie en una azotea de Lima al amanecer mirando la ciudad, luz dorada y destello de lente, la cámara gira suave alrededor de él. Viento y ciudad despertando, sin voz. Cinematográfico, grano de película.', '[]'::jsonb, null, false, false, 42),
  ('machu-picchu', 'Motivación y paisajes', 'Machu Picchu desde el aire', 'Paisajes épicos del Perú para intros y fondos.', '/showcase/machu-picchu.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'alejamiento', 'Toma aérea cinematográfica de Machu Picchu al amanecer, nubes bajas moviéndose entre las montañas, luz dorada, la cámara se aleja lentamente revelando el valle. Viento suave y música épica, sin voz.', '[]'::jsonb, null, false, false, 43),
  ('lluvia-ventana', 'Motivación y paisajes', 'Lluvia en la ventana', 'Fondo tranquilo para frases o reflexiones.', '/showcase/idea-lluvia-ventana.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Primer plano de gotas de lluvia resbalando por una ventana de noche, detrás las luces de la ciudad desenfocadas en bokeh naranja y azul, una taza de café humeando en el borde. Sonido de lluvia suave, sin voz.', '[]'::jsonb, null, false, false, 44),
  ('cima-montana', 'Motivación y paisajes', 'Llegar a la cima', 'La toma épica para hablar de disciplina y metas.', '/showcase/idea-cima-montana.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'orbita', 'Un montañista con casaca roja llega a la cima nevada de una montaña de los Andes al amanecer y levanta los brazos, nubes debajo, la cámara gira a su alrededor. Viento fuerte y música épica, sin voz.', '[]'::jsonb, null, false, false, 45),
  ('lima-noche', 'Motivación y paisajes', 'Lima de noche', 'La ciudad que nunca para: intro perfecta para tu canal.', '/showcase/idea-lima-noche.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'paneo', 'Toma aérea nocturna de Miraflores y la Costa Verde de Lima, autos con estelas de luz por la vía, edificios iluminados y el mar oscuro, la cámara se desplaza de lado. Música electrónica suave, sin voz.', '[]'::jsonb, null, false, false, 46),
  ('perro-chef', 'Mascotas', 'Perrito chef', 'Mascotas haciendo cosas de humanos: siempre funcionan.', '/showcase/idea-perro-chef.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Plano general de un perrito golden retriever de pie sobre sus patas traseras frente a una cocina, visto de cuerpo entero, con gorro alto blanco de chef y delantal blanco bien visible en el pecho. Sostiene con la pata una sartén y hace saltar un panqueque, que gira en el aire y vuelve a caer en la sartén. No muerde ni come el panqueque. Sonido de la sartén y un ladrido feliz. Video realista, luz cálida de cocina.', '[]'::jsonb, null, false, false, 47),
  ('gato-jefe', 'Mascotas', 'El gato jefe', 'Memes de oficina con tu mascota como protagonista.', '/showcase/idea-gato-jefe.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto realista de un gato naranja con lentes y corbata sentado en una silla de oficina de cuero frente a un escritorio con laptop, mirando a la cámara con cara seria, oficina moderna de fondo.', '[]'::jsonb, null, false, false, 48),
  ('mascota-habla', 'Mascotas', 'Tu mascota habla', 'Ponle voz a tu perro: el formato que todos comentan.', '/showcase/idea-mascota-habla.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Un perro bulldog francés sentado en un sofá mira a la cámara y mueve la boca diciendo con voz grave y graciosa: «¿Otra vez llegaste tarde? Me debes dos paseos». Sonido ambiente de casa. Video realista.', '[]'::jsonb, null, false, false, 49),
  ('outfit-calle', 'Moda y belleza', 'Outfit del día', 'Caminata en la calle con ropa de tu tienda.', '/showcase/idea-outfit-calle.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'paneo', 'Una joven latina camina con seguridad por una calle de Barranco con murales de colores, lleva chaqueta denim, pantalón negro y zapatillas blancas, la cámara la sigue de lado. Música urbana suave, sin voz.', '[]'::jsonb, null, false, false, 50),
  ('antes-despues-makeup', 'Moda y belleza', 'Maquillaje antes y después', 'La transformación que se guarda y se comparte.', '/showcase/idea-antes-despues-makeup.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Imagen vertical dividida en dos mitades por una línea blanca. Mitad de arriba: rostro de una mujer latina sin nada de maquillaje, cara lavada, cabello recogido, luz plana, con la etiqueta grande ANTES en letras blancas sobre fondo negro. Mitad de abajo: la misma mujer con maquillaje de fiesta, sombras doradas, delineado, pestañas largas, labios rojos intensos y cabello suelto con ondas, con la etiqueta grande DESPUÉS en letras blancas sobre fondo negro.', '[]'::jsonb, null, false, false, 51),
  ('unas-diseno', 'Moda y belleza', 'Uñas de diseño', 'Fotos macro que muestran el detalle de tu trabajo.', '/showcase/idea-unas-diseno.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto macro realista de una mano con uñas largas almendradas de diseño en tonos lila y dorado con brillos, sosteniendo una taza blanca, fondo rosado pastel desenfocado, luz suave de estudio.', '[]'::jsonb, null, false, false, 52),
  ('profesor-dato', 'Educación y tips', 'Profe explica en 5 segundos', 'Un dato útil, dicho rápido y con cara amable.', '/showcase/idea-profesor-dato.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Un profesor joven con camisa celeste frente a una pizarra en un aula luminosa mira a la cámara y dice: «Si ahorras diez soles al día, al año tienes más de tres mil». Sonido de aula tranquila. Video realista.', '[]'::jsonb, null, false, false, 53),
  ('infografia-pasos', 'Educación y tips', 'Infografía en 3 pasos', 'Enseña algo en una sola imagen que la gente guarda.', '/showcase/idea-infografia-pasos.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Infografía vertical de diseño plano con fondo azul oscuro. Arriba el título grande blanco 3 PASOS PARA AHORRAR. Debajo tres tarjetas grandes apiladas, cada una con un número grande 1, 2 y 3 y un ícono grande: una alcancía, un calendario y una flecha subiendo, y una sola palabra grande al lado: ANOTA, SEPARA, CRECE. Sin texto pequeño, sin párrafos.', '[]'::jsonb, null, false, false, 54),
  ('chasqui', 'Educación y tips', 'Dato histórico: los chasquis', 'Historia del Perú contada como película.', '/showcase/idea-chasqui.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'paneo', 'Plano cinematográfico de un chasqui inca corriendo por un camino de piedra en las montañas de los Andes, con su pututo y quipu, al amanecer. Un narrador dice: «Los chasquis llevaban mensajes por relevos a lo largo del Qhapaq Ñan». Viento y pasos, música andina.', '[]'::jsonb, null, false, false, 55),
  ('coach-gym', 'Fitness y salud', 'Coach en el gimnasio', 'Tips de entrenamiento con voz, sin pagar un modelo.', '/showcase/idea-coach-gym.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Primer plano del rostro y los hombros de una entrenadora latina de 35 años con sudadera gris gruesa de manga larga, lisa y cerrada hasta el cuello. Detrás solo hay una pared lisa de gimnasio, desenfocada, sin máquinas. Mira a la cámara y dice con energía en español latino: "Tres series de esto y me cuentas mañana". Cámara fija, luz de gimnasio, sonido de pesas al fondo.', '[]'::jsonb, null, false, false, 56),
  ('bowl-saludable', 'Fitness y salud', 'Plato saludable', 'Comida fit que se ve rica: perfecta para nutricionistas.', '/showcase/idea-bowl-saludable.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto gastronómica cenital de un bowl saludable con quinua, palta en láminas, pollo a la plancha, tomates cherry, garbanzos y semillas, sobre una mesa de madera clara con luz natural.', '[]'::jsonb, null, false, false, 57),
  ('yoga-amanecer', 'Fitness y salud', 'Yoga frente al mar', 'Calma y movimiento: fondo para mensajes de bienestar.', '/showcase/idea-yoga-amanecer.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'orbita', 'Una mujer hace una postura de yoga sobre un mat en la arena frente al mar al amanecer, la cámara gira lento a su alrededor, luz dorada. Sonido de olas y música relajante, sin voz.', '[]'::jsonb, null, false, false, 58),
  ('fruti-boda', 'Frutinovelas', 'La boda interrumpida', 'Capítulo clásico: la rival entra a la iglesia justo antes del «sí, acepto».', '/showcase/idea-fruti-boda.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Animación 3D estilo película animada: una iglesia decorada con flores, una novia fresa con velo blanco y ojos grandes junto a un novio plátano con traje azul frente al altar. En la puerta aparece una piña con gafas de sol y vestido negro, todos los invitados frutas se voltean sorprendidos. Iluminación dramática de telenovela. Sin humanos, sin texto.', '[]'::jsonb, null, false, false, 59),
  ('fruti-suegra', 'Frutinovelas', 'La suegra chismosa', 'Personaje fijo que da risa y mueve la trama de todos los capítulos.', '/showcase/idea-fruti-suegra.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Animación 3D cinematográfica: una sandía anciana con rulos, collar de perlas y delantal floreado, ojos grandes y cejas levantadas, espiando por la ventana de una cocina mientras sostiene una taza de té. Detrás, una palta joven discute en voz baja por teléfono. Colores saturados, luz cálida dramática. Sin humanos, sin texto.', '[]'::jsonb, null, false, false, 60),
  ('fruti-llamada', 'Frutinovelas', 'Video: la llamada que lo cambia todo', 'Animar la escena con diálogo corto es lo que hace que se sienta telenovela.', '/showcase/idea-fruti-llamada.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'acercamiento', 'Animación 3D estilo película animada: una fresa elegante de aspecto adulto, con vestido rojo largo y aretes dorados, ojos grandes llenos de lágrimas, en una cocina de noche, sostiene junto a la oreja el auricular de un teléfono fijo antiguo de color rojo, con cable. Dice con voz dramática y quebrada en español latino: "¿Tú sabías que él me mintió?". Música de violines de suspenso. La imagen no lleva ninguna letra.', '[]'::jsonb, null, false, false, 61),
  ('fruti-juicio', 'Frutinovelas', 'Juicio en el mercado', 'Un escenario peruano reconocible hace que el público se identifique y comente.', '/showcase/idea-fruti-juicio.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Animación 3D cinematográfica: un mercado limeño de frutas lleno de gente, un mango juez con peluca blanca y mazo golpea un puesto de madera, frente a él un limón acusado con cara de nervios y una naranja abogada con maletín. Luz cálida de mediodía, colores saturados, expresiones exageradas de telenovela. Sin humanos, sin texto.', '[]'::jsonb, null, false, false, 62),
  ('fruti-portada', 'Frutinovelas', 'Portada de capítulo', 'La portada decide si abren el video: tema claro, 4 palabras y colores fuertes.', '/showcase/idea-fruti-portada.jpg', null, 'image', 'nano-banana-pro', '9:16', null, null, null, 'Portada de TikTok de telenovela animada 3D: un plátano con cara de traición en primer plano, ojos enormes y ceja arqueada, fondo rojo y negro con destellos dorados. Texto grande arriba: «ME ENGAÑASTE» y abajo la etiqueta «CAPÍTULO 7». Que dé ganas de ver el video sin revelar el giro.', '[]'::jsonb, null, false, false, 63),
  ('fruti-heladeria', 'Frutinovelas', 'Cita en la heladería', 'Escena romántica para abrir la serie y presentar a la pareja protagonista.', '/showcase/idea-fruti-heladeria.jpg', null, 'video', 'veo-fast', '9:16', 8, '720p', 'orbita', 'Animación 3D estilo película animada: una pareja de frutas, una fresa con coletas y un arándano con chaqueta de cuero, comparten un helado en una heladería de colores pastel de noche. Ella se ríe con ternura y le dice con voz dulce: «Nunca había sido tan feliz». Música romántica suave. Sin subtítulos ni texto.', '[]'::jsonb, null, false, false, 64),
  ('anime-azotea', 'Anime novela', 'Confesión en la azotea', 'Primer capítulo: una escena tranquila que deja una pregunta.', null, null, 'image', 'nano-banana-2', '9:16', null, null, null, 'Ilustración anime original de drama: una estudiante de pelo castaño con lazo rojo y uniforme azul mira el atardecer desde la azotea de su escuela, un joven de espaldas con audífonos al fondo. Cielo naranja y rosado, fondos pintados a mano, colores suaves. Sin texto.', '[]'::jsonb, null, false, false, 65),
  ('anime-lluvia', 'Anime novela', 'Estación bajo la lluvia', 'La lluvia y el tren dan emoción sin necesitar movimientos complejos.', null, null, 'video', 'veo-fast', '9:16', 8, '720p', 'acercamiento', 'Animación anime original de drama: una joven de pelo negro corto y paraguas transparente espera en una estación de tren bajo la lluvia, las luces de neón se reflejan en el piso mojado. Levanta la mirada y dice en voz suave: «Dijiste que vendrías». Sonido de lluvia y piano melancólico. Sin subtítulos.', '[]'::jsonb, null, false, false, 66),
  ('anime-rival', 'Anime novela', 'La rival transferida', 'Un personaje nuevo mueve la trama del siguiente capítulo.', null, null, 'image', 'nano-banana-pro', '9:16', null, null, null, 'Ilustración anime original de drama: una chica de pelo largo plateado y ojos violeta, uniforme gris con chaqueta abierta, entra al salón de clases con mirada segura mientras los demás la miran sorprendidos. Luz de mañana por las ventanas, colores suaves con acento violeta. Sin texto.', '[]'::jsonb, null, false, false, 67),
  ('anime-festival', 'Anime novela', 'Festival de verano', 'Escena de romance con luces y fuegos artificiales, ideal para portada.', null, null, 'image', 'qwen-image', '9:16', null, null, null, 'Ilustración anime original: una pareja de jóvenes con yukata sostiene faroles en un festival de verano de noche, fuegos artificiales rojos y dorados en el cielo, puestos de comida con luces cálidas. Composición cinematográfica, colores suaves. Sin texto.', '[]'::jsonb, null, false, false, 68),
  ('anime-portada', 'Anime novela', 'Portada de episodio', 'Un rostro en primer plano y un título corto retienen al público.', null, null, 'image', 'nano-banana-pro', '9:16', null, null, null, 'Portada de serie anime original: primer plano de una protagonista de ojos grandes con lágrimas y expresión de sorpresa, fondo azul marino con destellos rosados. Texto grande arriba: «NO ERA ÉL» y abajo la etiqueta «EPISODIO 3». Que dé ganas de ver el siguiente sin revelar el giro.', '[]'::jsonb, null, false, false, 69),
  ('whatif-mar', 'Historias ficticias', '¿Y si el mar llegara a Lima?', 'Escenario imaginario espectacular. Marca el video como ficción hecha con IA.', null, null, 'image', 'nano-banana-2', '9:16', null, null, null, 'Imagen cinematográfica de ciencia ficción: la costa de Lima de noche con el mar subiendo hasta los acantilados de Miraflores, edificios iluminados y calles inundadas, luz de luna fría con un acento cálido de faroles. Sin personas reconocibles, sin logos ni texto.', '[]'::jsonb, null, false, false, 70),
  ('whatif-sin-internet', 'Historias ficticias', '¿Y si todo internet se apagara un día?', 'Pregunta que invita a comentar. Es una historia imaginaria, no una noticia.', null, null, 'image', 'qwen-image', '9:16', null, null, null, 'Imagen cinematográfica realista de ciencia ficción: una avenida de Lima al mediodía donde todas las personas miran pantallas negras de celulares con cara de desconcierto, semáforos apagados, luz fría de nublado. Sin logos ni texto.', '[]'::jsonb, null, false, false, 71),
  ('whatif-ciudad-flotante', 'Historias ficticias', '¿Y si Lima fuera una ciudad flotante?', 'Mundo imaginario fácil de animar con movimiento lento.', null, null, 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Una ciudad futurista flotando sobre las nubes al amanecer con puentes de cristal y jardines colgantes, la cámara avanza lentamente entre los edificios, luz dorada. Sonido ambiente suave de viento y música instrumental de ciencia ficción. Escena imaginaria, sin texto.', '[]'::jsonb, null, false, false, 72),
  ('whatif-sin-gravedad', 'Historias ficticias', '¿Y si la gravedad fallara 10 segundos?', 'Escena de ficción con objetos cotidianos flotando, ideal para un gancho corto.', null, null, 'video', 'veo-fast', '9:16', 8, '720p', 'fija', 'Una cocina moderna donde de pronto las tazas, cucharas y frutas empiezan a flotar lentamente en el aire, una niña sonríe sorprendida y estira la mano para atrapar una manzana. Dice en voz baja: «Esto no está pasando». Sonido ambiente y música de misterio suave. Sin subtítulos.', '[]'::jsonb, null, false, false, 73),
  ('whatif-sin-sol', 'Historias ficticias', '¿Y si el sol saliera por el oeste?', 'Pregunta curiosa; puedes explicar la ciencia real en la narración, aclarando que es hipotético.', null, null, 'image', 'z-image', '9:16', null, null, null, 'Imagen cinematográfica de un amanecer sobre el mar del Pacífico visto desde una playa de Lima, el sol sale por el lado del océano con luz anaranjada, gente mirando asombrada en la orilla. Atmósfera de cine, sin logos ni texto.', '[]'::jsonb, null, false, false, 74),
  ('modelo-gym', 'Modelos IA', 'Creadora fitness en el gimnasio', 'Mismo rostro y cuerpo en todas las fotos para promocionar ropa deportiva o suplementos.', '/showcase/idea-modelo-gym.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto realista de celular de una creadora fitness latina de 26 años, cabello castaño largo recogido en cola alta, lunar sobre el labio, contextura atlética, en un gimnasio moderno de Lima con espejo grande, conjunto deportivo negro, tomándose una selfie en el espejo con el celular. Luz de gimnasio natural, piel real con textura, sin filtros. Sin texto.', '[]'::jsonb, null, false, false, 75),
  ('modelo-ropa', 'Modelos IA', 'Outfit para tienda de ropa', 'Prueba de prendas sin contratar modelo. Adjunta la foto de tu prenda como imagen de referencia.', '/showcase/idea-modelo-ropa.jpg', null, 'image', 'nano-banana-pro', '9:16', null, null, null, 'Foto de catálogo realista de una modelo latina de 24 años, cabello negro lacio a los hombros, cejas definidas, de pie en una calle soleada de Barranco, vistiendo el polo y el jean de la imagen de referencia, mirando a la cámara con una sonrisa leve. Luz natural de la tarde, foto de celular. Sin texto.', '[]'::jsonb, null, false, false, 76),
  ('modelo-skincare', 'Modelos IA', 'Rutina de skincare', 'Foto con producto en mano, ideal para afiliados y tiendas de belleza. Adjunta la foto de tu frasco como imagen de referencia.', '/showcase/idea-modelo-skincare.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Foto realista de celular de una creadora de contenido latina de 27 años con piel natural y pecas leves, en un baño luminoso con toalla blanca en la cabeza, sosteniendo junto a su cara un frasco de sérum como el de la imagen de referencia, sonriendo. Luz suave de ventana. Sin texto adicional.', '[]'::jsonb, null, false, false, 77),
  ('modelo-unboxing', 'Modelos IA', 'Unboxing hablado', 'Video corto con voz en español para mostrar la caja del producto como si fuera real.', '/showcase/idea-modelo-unboxing.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Una joven peruana sentada en el sofá de su sala abre una caja de cartón con un producto y dice con voz emocionada: «Por fin llegó mi pedido, miren cómo vino». Cámara de celular en mano, luz natural de la tarde, sonido ambiente de casa y papel de la caja. Sin subtítulos.', '[]'::jsonb, null, false, false, 78),
  ('modelo-barista', 'Modelos IA', 'Creador hombre: reseña en café', 'El creador virtual también puede ser hombre: ideal para tecnología, gadgets y finanzas.', '/showcase/idea-modelo-barista.jpg', null, 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Un joven latino de 28 años con barba corta y chompa gris, sentado en una cafetería con una laptop, mira a la cámara del celular y dice con voz tranquila: «Con esta herramienta ahorro dos horas al día». Murmullo de cafetería, taza sobre la mesa, luz cálida de ventana. Cámara en mano.', '[]'::jsonb, null, false, false, 79),
  ('mini-ascensor', 'Miniseries TikTok', 'Miniserie: el ascensor', 'Un espacio cerrado es el escenario más barato para generar tensión.', '/showcase/idea-mini-ascensor.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'acercamiento', 'Plano cinematográfico dentro de un ascensor antiguo de paredes de madera: una mujer de 30 años con blazer oscuro, de pie y con la boca cerrada, mira hacia arriba, asustada. La luz del techo parpadea. Se oye una voz susurrante por el parlante, fuera de cuadro: "Hoy no deberías haber venido". Ella no habla. Zumbido eléctrico, sin música. Sin subtítulos.', '[]'::jsonb, null, false, false, 80),
  ('mini-enfermera', 'Miniseries TikTok', 'Miniserie: turno de noche', 'Protagonista fija, un hospital y un secreto que se revela capítulo a capítulo.', '/showcase/idea-mini-enfermera.jpg', null, 'image', 'nano-banana-pro', '9:16', null, null, null, 'Retrato cinematográfico de una enfermera latina de 30 años, cabello recogido, ojeras leves, uniforme verde, parada en un pasillo vacío de hospital de noche con una carpeta en la mano, mirando hacia atrás con preocupación. Luz fluorescente fría con un punto de luz cálida al fondo. Sin texto.', '[]'::jsonb, null, false, false, 81),
  ('mini-herencia', 'Miniseries TikTok', 'Miniserie: la herencia', 'Familia, notario y un testamento: la receta perfecta de drama corto.', '/showcase/idea-mini-herencia.jpg', null, 'video', 'veo-fast', '9:16', 8, '720p', 'acercamiento', 'Interior de una oficina de notario en Lima, tarde. Tres hermanos adultos sentados alrededor de una mesa de madera mientras el notario abre un sobre sellado. Uno de ellos se levanta de golpe y dice con voz furiosa: «¡Eso no puede ser cierto!». Cámara lenta de acercamiento, música tensa que se corta de golpe. Sin subtítulos.', '[]'::jsonb, null, false, false, 82),
  ('mini-vecino', 'Miniseries TikTok', 'Miniserie: el vecino nuevo', 'Suspenso: algo raro en la casa de al lado y una pregunta que obliga a ver la parte 2.', '/showcase/idea-mini-vecino.jpg', null, 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Plano nocturno desde una ventana: una mujer joven mira a través de las cortinas la casa de su vecino nuevo, donde todas las luces se apagan de golpe. Susurra: «Hace tres días que no sale… y tiene mi nombre en el buzón». Sonido de grillos y viento. Cámara en mano, luz azulada de luna. Sin subtítulos.', '[]'::jsonb, null, false, false, 83),
  ('mini-portada', 'Miniseries TikTok', 'Portada de la serie', 'Una portada con «PARTE 2» y un solo elemento en foco retiene a los seguidores.', '/showcase/idea-mini-portada.jpg', null, 'image', 'nano-banana-pro', '9:16', null, null, null, 'Portada de TikTok de miniserie de suspenso: primer plano de un taxista latino de 40 años con expresión de miedo bajo la lluvia de noche, luces de neón rojas y azules reflejadas en su cara. Texto grande arriba: «¿QUIÉN LO ENVIÓ?» y abajo la etiqueta «PARTE 2». Estilo cinematográfico, contraste alto.', '[]'::jsonb, null, false, false, 84),
  ('granja-miniatura', 'Tecnología y granjas', 'Granja en miniatura tilt-shift', 'Efecto maqueta: tu caja de iPhones parece un mundo diminuto y detiene el scroll.', '/showcase/idea-granja-miniatura.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía tilt-shift de una caja de metal negra llena de iPhones encendidos en filas con cables USB-C, vista como una maqueta en miniatura, personas diminutas caminando entre los cables, foco selectivo, colores saturados, luz azul. Sin texto.', '[{"titulo":"Con obreros","prompt":"Fotografía tilt-shift de una caja de metal negra llena de iPhones encendidos en filas con cables USB-C, vista como una maqueta en miniatura, obreros diminutos con casco revisando los cables entre los teléfonos, foco selectivo, luz [color: azul / cian]. Sin texto."},{"titulo":"Ciudad de cables","prompt":"Fotografía tilt-shift de una caja de metal negra llena de iPhones encendidos en filas con cables USB-C, vista como una ciudad nocturna en miniatura: las pantallas parecen edificios encendidos y autos diminutos circulan sobre los cables. Sin texto."},{"titulo":"Sobre el escritorio","prompt":"Maqueta tilt-shift de una caja de iPhones en filas sobre un escritorio de [material: madera / vidrio], una taza de café gigante al lado, foco selectivo. Sin texto."}]'::jsonb, 'Tendencia: mundos en miniatura tilt-shift.', true, false, 85),
  ('granja-afiche', 'Tecnología y granjas', 'Afiche de película de la caja', 'Tu caja de iPhones como estreno de Hollywood: gracioso y muy compartible.', '/showcase/idea-granja-afiche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche de película de acción de Hollywood protagonizado por una caja de metal negra abierta, vista de frente, llena de iPhones encendidos en filas con sus cámaras y bordes bien reconocibles y cables USB-C, en el centro, con luces azules dramáticas, humo y chispas. Título grande arriba: "LA CAJA". Abajo, en letras pequeñas: "PRÓXIMAMENTE".', '[{"titulo":"Terror","prompt":"Afiche de película de terror: una caja de metal llena de iPhones en filas brilla en un sótano oscuro. Título grande: \"NO LA TOQUES\"."},{"titulo":"Comedia","prompt":"Afiche de comedia de los 90 con una caja llena de iPhones en filas sobre fondo [color: amarillo / celeste]. Título grande: \"MI SOCIO EL ROUTER\"."},{"titulo":"Ciencia ficción","prompt":"Afiche de ciencia ficción: una caja de iPhones en filas flota sobre la ciudad de Lima de noche con rayos de luz. Título grande: \"40 CELULARES\"."}]'::jsonb, 'Tendencia: afiche de Hollywood de cosas cotidianas.', true, false, 86),
  ('granja-macro-cables', 'Tecnología y granjas', 'Macro de cables y pantallas', 'Primer plano hipnótico: cables ordenados y pantallas encendidas, ideal para un gancho sin rostro.', '/showcase/idea-granja-macro-cables.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Primer plano macro de una fila de iPhones encendidos de pie dentro de una caja de metal negra, cada uno con un cable USB-C en el puerto inferior, cables ordenados, profundidad de campo corta, luces LED azules y cian, de noche. Foto realista. Sin texto.', '[{"titulo":"Luz morada","prompt":"Primer plano macro de iPhones de pie en una caja negra con cables USB-C, profundidad de campo corta, luz LED [color: morada / rosada]. Foto realista. Sin texto."},{"titulo":"Desde arriba","prompt":"Vista cenital de una caja de metal llena de iPhones en filas con cables USB-C ordenados y pantallas encendidas, luz azul. Foto realista. Sin texto."},{"titulo":"Con ventilador","prompt":"Primer plano de una caja de metal negra llena de iPhones en filas con cables USB-C y, a un lado, un pequeño ventilador redondo de aspas encendido, luz [color: azul / blanca]. Foto realista. Sin texto ni logos."}]'::jsonb, 'Refuerzo de Tecnología y granjas: primer plano, el punto fuerte del estilo.', true, false, 87),
  ('granja-revista', 'Tecnología y granjas', 'Portada de revista de tu granja', 'Como si tu negocio saliera en la portada: prueba social con humor.', '/showcase/idea-granja-revista.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Portada de una revista de negocios con una caja de metal negra abierta llena de iPhones encendidos en filas, con sus cámaras y bordes bien reconocibles, como protagonista, sobre fondo oscuro con luz azul. Título grande arriba: "NEGOCIOS". Texto abajo: "La caja que trabaja sola". Ningún otro texto.', '[{"titulo":"Tecnología","prompt":"Portada de revista de tecnología con una caja llena de iPhones en filas, fondo [color: negro / azul]. Título grande: \"TECH\". Texto abajo: \"40 pantallas, 1 persona\"."},{"titulo":"Con el dueño","prompt":"Portada de revista: una persona joven sonríe con los brazos cruzados junto a una caja llena de iPhones en filas. Título grande: \"EMPRENDER\". Texto abajo: \"Empezó en su cuarto\"."},{"titulo":"Retro","prompt":"Portada de revista retro de los 80 con una caja de iPhones en filas y colores neón. Título grande: \"FUTURO\"."}]'::jsonb, 'Tendencia: Polaroid y portada de revista.', true, false, 88),
  ('selladora-afiche', 'Negocios y máquinas', 'Afiche de película de tu selladora', 'La selladora de vasos como héroe de acción: tu máquina se vuelve el personaje.', '/showcase/idea-selladora-afiche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche de película de acción de Hollywood protagonizado por una máquina selladora de vasos de mostrador, de acero inoxidable con una palanca negra arriba y un vaso de plástico con jugo debajo de la placa selladora, en un local de bebidas, con luces dramáticas y chispas. Título grande arriba: "LA SELLADORA". Abajo, en letras pequeñas: "NUNCA FALLA UN VASO".', '[{"titulo":"Comedia","prompt":"Afiche de comedia con una máquina selladora de vasos de mostrador, de acero con una palanca negra, en el centro, sobre fondo [color: amarillo / rosado] y vasos de plástico con tapa de film volando alrededor. Título grande: \"SELLADA Y MUY FELIZ\"."},{"titulo":"Terror","prompt":"Afiche de terror: una máquina selladora de vasos de mostrador, de acero con una palanca negra y un vaso de plástico debajo, brilla en un local de bebidas oscuro. Título grande: \"EL ÚLTIMO VASO\"."},{"titulo":"Romance","prompt":"Afiche romántico: una máquina selladora de vasos de mostrador, de acero con una palanca negra, y al lado un vaso de plástico con jugo sellado con film, al atardecer. Título grande: \"PARA SIEMPRE SELLADOS\"."}]'::jsonb, 'Tendencia: afiche de Hollywood de cosas cotidianas.', true, false, 89),
  ('maquina-cascos-miniatura', 'Negocios y máquinas', 'Lava cascos en miniatura', 'Tu máquina como maqueta: un formato de tendencia que muestra el producto sin venderlo.', '/showcase/idea-maquina-cascos-miniatura.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía tilt-shift de una máquina de autoservicio lava cascos, un gabinete alto negro y azul con una cámara de vidrio y un casco de moto adentro, en el pasillo de un centro comercial visto como una maqueta en miniatura, personas diminutas con cascos de moto haciendo fila frente a la máquina, foco selectivo, colores saturados. Sin texto.', '[{"titulo":"En la calle","prompt":"Tilt-shift de una máquina de autoservicio lava cascos, un gabinete alto negro y azul con una cámara de vidrio y un casco de moto adentro, en una esquina de [ciudad: Lima / Medellín] como maqueta, motos diminutas alrededor, foco selectivo. Sin texto."},{"titulo":"En la plaza","prompt":"Tilt-shift de una máquina de autoservicio lava cascos, un gabinete alto negro y azul con una cámara de vidrio y un casco de moto adentro, en una plaza con árboles y bancas como maqueta, motociclistas diminutos alrededor, foco selectivo. Sin texto."},{"titulo":"Fila de motos","prompt":"Tilt-shift visto desde arriba de una máquina de autoservicio lava cascos, un gabinete alto negro y azul con una cámara de vidrio y un casco de moto adentro, en una calle como maqueta, con una fila larga de motos diminutas esperando, foco selectivo. Sin texto."}]'::jsonb, 'Tendencia: mundos en miniatura tilt-shift.', true, false, 90),
  ('maquina-cascos-figurita', 'Negocios y máquinas', 'Figurita del lava cascos', 'La máquina convertida en juguete de colección: gracioso y fácil de recordar.', '/showcase/idea-maquina-cascos-figurita.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Réplica de juguete coleccionable a escala 1/7 de una máquina de autoservicio que limpia cascos de moto: un gabinete cuadrado negro mate con el frente y el techo totalmente lisos, una franja azul lisa abajo y una gran ventana de vidrio en el centro, dentro un solo casco de moto rojo diminuto sobre un soporte, con gotas de agua en el vidrio, sobre una base acrílica transparente, en un escritorio. Foto de producto realista, luz de estudio suave, fondo desenfocado. Sin texto.', '[{"titulo":"Con su empaque","prompt":"Réplica de juguete 1/7 de una máquina de autoservicio lava cascos, un gabinete negro con paneles azules lisos, sin letreros, con una cámara de vidrio y solo un casco diminuto dentro, sin muñecos, junto a una caja de cartón de juguete vacía de color [color: rojo / azul], base acrílica, foto de producto. Sin texto."},{"titulo":"En la mano","prompt":"Mano real con la palma abierta sosteniendo una réplica de juguete diminuta de una máquina de autoservicio lava cascos, un gabinete negro y azul liso con una cámara de vidrio y un casco diminuto dentro, sin muñecos, fondo de un mall desenfocado, foto realista. Sin texto."},{"titulo":"Colección","prompt":"Tres réplicas de juguete pequeñas y del mismo tamaño, en fila sobre un estante: un gabinete negro con un casco de moto dentro de una cámara de vidrio, una máquina selladora de vasos de acero con palanca y una máquina expendedora roja de bebidas, foto realista. Sin texto."}]'::jsonb, 'Tendencia: figurita coleccionable 1/7 con base acrílica (posible fatiga).', true, false, 91),
  ('brainrot-figurita', 'Brainrot', 'Figurita de tu personaje brainrot', 'Convierte a tu personaje en pieza de colección y deja que la gente pida el suyo.', '/showcase/idea-brainrot-figurita.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Figurita coleccionable a escala 1/7 de un cuy animado con lentes oscuros y cadena dorada, sobre una base acrílica transparente, en un escritorio. Foto de producto realista, luz de estudio suave, fondo desenfocado. Sin texto.', '[{"titulo":"Llama","prompt":"Figurita 1/7 de una llama animada con [accesorio: corona / audífonos] sobre base acrílica, foto de producto realista. Sin texto."},{"titulo":"Pollo","prompt":"Figurita 1/7 de un pollo a la brasa animado con piernas y brazos, sobre base acrílica, foto de producto realista. Sin texto."},{"titulo":"Choclo","prompt":"Figurita 1/7 de una mazorca de maíz amarilla animada, con sus granos visibles, sobre base acrílica, foto de producto realista. Sin texto."}]'::jsonb, 'Tendencia: figurita coleccionable 1/7 con base acrílica (posible fatiga).', true, false, 92),
  ('mascota-afiche', 'Mascotas', 'Tu mascota en un afiche de cine', 'Tu perro protagonista de su propia película: el formato que todos quieren compartir.', '/showcase/idea-mascota-afiche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche de película de acción de Hollywood protagonizado por un perro mestizo marrón con gafas de sol y chaqueta de cuero, explosiones suaves detrás. Título grande arriba: "EL FIRULAIS". Abajo, en letras pequeñas: "ESTE VERANO".', '[{"titulo":"Gato villano","prompt":"Afiche de película: un gato [color: negro / blanco] como villano elegante en un sillón. Título grande: \"MICHI\"."},{"titulo":"Comedia romántica","prompt":"Afiche de comedia romántica con dos perros en un parque al atardecer. Título grande: \"AMOR DE PARQUE\"."},{"titulo":"Terror","prompt":"Afiche de terror: un gato mira fijo desde la oscuridad de un pasillo. Título grande: \"LAS 3 DE LA MAÑANA\"."}]'::jsonb, 'Tendencia: afiche de Hollywood de cosas cotidianas.', true, false, 93),
  ('mascota-miniatura', 'Mascotas', 'Mascota gigante en ciudad miniatura', 'Tu mascota como gigante tierno en un mundo diminuto.', '/showcase/idea-mascota-miniatura.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía tilt-shift de un perro mestizo marrón gigante y tierno caminando entre edificios en miniatura de una ciudad latinoamericana, autos diminutos y personas pequeñas mirando hacia arriba, foco selectivo, luz de mañana. Sin texto.', '[{"titulo":"Gato","prompt":"Tilt-shift de un gato [color: naranja / gris] gigante durmiendo sobre edificios en miniatura, foco selectivo. Sin texto."},{"titulo":"En la playa","prompt":"Tilt-shift de un perro gigante jugando en una playa en miniatura con sombrillas diminutas, foco selectivo. Sin texto."},{"titulo":"En el parque","prompt":"Tilt-shift de un conejo gigante en un parque en miniatura con niños diminutos, foco selectivo. Sin texto."}]'::jsonb, 'Tendencia: mundos en miniatura tilt-shift.', true, false, 94),
  ('influencer-polaroid', 'Influencers IA', 'Polaroid de tu creadora virtual', 'Estética de foto instantánea: da cercanía real a una cuenta de IA.', '/showcase/idea-influencer-polaroid.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto instantánea estilo Polaroid de una mujer latina de 38 años, adulta, con arrugas de expresión en los ojos, riendo en una azotea de Lima al atardecer, con suéter holgado de manga larga y cuello alto, grano de película, colores cálidos y desvaídos, flash suave, marco blanco de la foto. Sin texto.', '[{"titulo":"En la playa","prompt":"Foto estilo Polaroid de una mujer latina de 38 años, con camisa holgada de manga larga abotonada hasta el cuello y pantalón largo de lino, en [lugar: Máncora / Cartagena] con el viento en el pelo, grano de película, marco blanco. Sin texto."},{"titulo":"Con amigas","prompt":"Foto estilo Polaroid de tres amigas latinas de unos 40 años riendo en una cafetería, flash directo, grano de película, marco blanco. Sin texto."},{"titulo":"De noche","prompt":"Foto estilo Polaroid de una mujer latina de 38 años de piel morena, con suéter holgado de manga larga y cuello alto, en una calle de Lima de noche con luces de neón sin letras, flash directo, colores desvaídos, marco blanco. Sin texto."}]'::jsonb, 'Tendencia: Polaroid y portada de revista.', true, false, 95),
  ('influencer-revista', 'Influencers IA', 'Portada de revista de tu creadora', 'Una portada da estatus de marca a tu personaje: ideal para perfil y destacados.', '/showcase/idea-influencer-revista.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Portada de una revista de moda con una mujer latina de 35 años, cabello negro, traje color crema con saco abotonado y blusa blanca de cuello alto debajo, mirando a la cámara sobre fondo liso. Título grande arriba: "VISTA". Texto al costado: "La nueva cara de Lima".', '[{"titulo":"Fitness","prompt":"Portada de revista de deporte con una mujer latina de 35 años con ropa deportiva de manga larga y pantalón largo, que cubre torso y vientre, en un parque. Título grande: \"FUERTE\". Texto: \"Rutina de 15 minutos\"."},{"titulo":"Negocios","prompt":"Portada de revista de negocios con un hombre latino de [edad: 30 / 45] años con saco. Título grande: \"LÍDER\". Texto: \"Empezó sin capital\"."},{"titulo":"Retro","prompt":"Portada de revista de moda de los 80 con una mujer latina de 35 años, con ropa de manga larga que cubre torso y vientre, y colores neón. Título grande: \"DIVA\". Ningún otro texto."}]'::jsonb, 'Tendencia: Polaroid y portada de revista.', true, false, 96),
  ('selfie-cleopatra', 'Historias ficticias', 'Selfie de Cleopatra', '¿Y si la historia hubiera tenido celular? Un formato simple que da para mil partes.', '/showcase/idea-selfie-cleopatra.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Selfie realista tomada con celular por Cleopatra sonriendo, con su tocado dorado y maquillaje egipcio, las pirámides y obreros detrás, luz de atardecer, encuadre de brazo extendido. Foto casual, sin ver el celular. Sin texto.', '[{"titulo":"Bolívar","prompt":"Selfie realista tomada con celular por Simón Bolívar, con uniforme azul de general de 1820 y patillas, su cara en primer plano, montado a caballo, su ejército detrás en [lugar: los Andes / una llanura], encuadre de brazo extendido. Foto casual, sin ver el celular. Sin texto."},{"titulo":"Inca en Machu Picchu","prompt":"Selfie realista de un emperador inca con tocado real de borla roja y plumas, orejeras de oro y túnica andina, sin barba, en Machu Picchu recién construido, obreros detrás, encuadre de brazo extendido. Sin texto."},{"titulo":"Vikingo","prompt":"Selfie realista tomada con celular por un vikingo con barba y casco de metal, en un barco en alta mar, otros vikingos remando detrás, encuadre de brazo extendido. Foto casual, sin ver el celular. Sin texto."}]'::jsonb, 'Tendencia: personajes históricos con selfie moderna.', true, false, 97),
  ('anuario-2085', 'Historias ficticias', 'Tu foto del anuario 2085', 'Así se vería el anuario de exalumnos del futuro: nostalgia al revés.', '/showcase/idea-anuario-2085.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto de anuario de exalumnos del año 2085: retrato de estudio de una mujer latinoamericana mestiza de 35 años, adulta, piel morena oscura, rostro ancho, pómulos anchos y nariz ancha, con peinado futurista plateado en forma de cresta geométrica brillante y chaqueta metálica holgada de manga larga y cuello alto cerrada, fondo azul moteado clásico de foto escolar, sonrisa tímida, grano de película. Sin texto.', '[{"titulo":"Hombre","prompt":"Foto de anuario de exalumnos del futuro: retrato de estudio de un exalumno latino de 40 años con visor [color: azul / rojo] y peinado futurista plateado, fondo azul moteado clásico de foto escolar, sonrisa tímida, grano de película. Sin texto."},{"titulo":"Profesor robot","prompt":"Foto de anuario escolar de 2085: un profesor androide con rostro sintético, foto de medio cuerpo, con saco y corbata, sonrisa amable, fondo azul moteado clásico de foto escolar. Sin texto."},{"titulo":"Foto de promoción","prompt":"Foto grupal de anuario de 2085: treinta exalumnos adultos con trajes plateados futuristas en gradas de un auditorio en Marte, detrás una cúpula de vidrio y el paisaje rojo de Marte. Sin texto."}]'::jsonb, 'Tendencia: anuario 2085.', true, false, 98),
  ('afiche-combi', 'Historias', 'La combi, la película', 'Lo cotidiano como superproducción de Hollywood: humor local que se comparte solo.', '/showcase/idea-afiche-combi.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche de película de acción de Hollywood protagonizado por una combi de transporte público de Lima, una minivan vieja genérica pintada de blanco y azul, vista de perfil, con el frente liso sin emblema ni parrilla y sin logos, saltando sobre un bache con chispas y polvo, luz dramática de atardecer. Título grande arriba: "LA COMBI". Abajo, en letras pequeñas: "BAJA EN LA ESQUINA".', '[{"titulo":"El mototaxi","prompt":"Afiche de película épica con un mototaxi peruano, una moto de tres ruedas con cabina y techo de lona, en un desierto al atardecer. Título grande: \"EL ÚLTIMO MOTOTAXI\"."},{"titulo":"La lavadora","prompt":"Afiche de terror con una lavadora vieja temblando en un cuarto oscuro. Título grande: \"ÚLTIMO CICLO\"."},{"titulo":"El wifi","prompt":"Afiche de ciencia ficción con un router parpadeando en un cuarto [estilo: oscuro / futurista]. Título grande: \"SIN SEÑAL\"."}]'::jsonb, 'Tendencia: afiche de Hollywood de cosas cotidianas.', true, false, 99),
  ('miniatura-lima', 'Motivación y paisajes', 'Lima en miniatura', 'Tu ciudad como maqueta perfecta: relajante, bonita y fácil de hacer en serie.', '/showcase/idea-miniatura-lima.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía tilt-shift de la Costa Verde de Lima vista como una maqueta en miniatura, el mar y los acantilados, autos diminutos en la avenida, foco selectivo, colores saturados, luz de atardecer. Sin texto.', '[{"titulo":"Plaza de Armas","prompt":"Tilt-shift de la Plaza de Armas de [ciudad: Cusco / Arequipa] como maqueta en miniatura, personas diminutas, foco selectivo. Sin texto."},{"titulo":"Mercado","prompt":"Tilt-shift de un mercado latinoamericano como maqueta, puestos de fruta diminutos, foco selectivo y colores saturados. Sin texto."},{"titulo":"Playa","prompt":"Tilt-shift de una playa llena de sombrillas de colores como maqueta en miniatura, foco selectivo. Sin texto."}]'::jsonb, 'Tendencia: mundos en miniatura tilt-shift.', true, false, 100),
  ('anime-acuarela', 'Anime novela', 'Tu escena en animación clásica japonesa', 'Estética de película animada de los 90: cálida, nostálgica y muy compartida.', '/showcase/idea-anime-acuarela.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Ilustración estilo animación japonesa clásica de los años 90, acuarela suave y fondos pintados a mano, plano general: una mujer latina de 40 años, de rostro maduro con suaves líneas de expresión, con blusa cerrada de manga larga y falda larga, sentada en una silla, toma café en una azotea de una ciudad con ropa tendida en cordeles a su lado, luz dorada de tarde, nubes grandes. Sin texto.', '[{"titulo":"Pueblo","prompt":"Ilustración de animación japonesa clásica: un hombre adulto de 35 años corre por un pueblo andino de casas de adobe junto a [animal: una alpaca blanca / un perro], montañas de los Andes y fondos en acuarela. Sin texto."},{"titulo":"Lluvia","prompt":"Ilustración de animación japonesa clásica: dos amigos adultos de unos 40 años esperan el bus bajo la lluvia en una calle de Lima, luz gris suave. Sin texto."},{"titulo":"Cocina","prompt":"Ilustración de animación japonesa clásica: una abuela cocina en una cocina cálida llena de ollas, vapor y luz de ventana. Sin texto."}]'::jsonb, 'Tendencia: redibujo en animación japonesa clásica.', true, false, 101),
  ('ceviche-afiche', 'Comida', 'El ceviche, la película', 'Tu plato estrella como superproducción: ideal para restaurantes con humor.', '/showcase/idea-ceviche-afiche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche de película épica de Hollywood protagonizado por un plato hondo de ceviche peruano en primer plano, abundantes cubos de pescado blanco crudo, húmedos y brillantes, marinados en limón, con tiras de cebolla morada en juliana y hojas de culantro encima, una rodaja redonda de camote cocido, naranja y lisa, a un lado, y un trozo de choclo con granos grandes de color amarillo pálido al otro, en el centro, olas de mar y rayos de luz dorada detrás. Título grande arriba: "EL CEVICHE". Abajo, en letras pequeñas: "HOY EN TU MESA".', '[{"titulo":"Pollo a la brasa","prompt":"Afiche de acción con un pollo a la brasa: un pollo asado entero, ya cocido, dorado y crujiente, sin cabeza ni plumas, servido en una bandeja con papas fritas, con llamas detrás. Título grande: \"A LA BRASA\"."},{"titulo":"Terror","prompt":"Afiche de terror con un plato de [plato: lentejas / sopa] en una cocina oscura. Título grande: \"OTRA VEZ\"."},{"titulo":"Romance","prompt":"Afiche romántico con dos tazas de café y un pan francés relleno de chicharrón en un plato, al amanecer. Título grande: \"DESAYUNO PARA DOS\". Ningún otro texto."}]'::jsonb, 'Tendencia: afiche de Hollywood de cosas cotidianas.', true, false, 102),
  ('producto-afiche', 'Productos y anuncios', 'Tu producto en un afiche de cine', 'El anuncio que no parece anuncio: tu producto como estrella de película.', '/showcase/idea-producto-afiche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche de película de acción de Hollywood protagonizado por un frasco de perfume negro sobre una roca volcánica, con humo, chispas y luz lateral dramática. Título grande arriba: "NOCHE". Abajo, en letras pequeñas: "ESTRENO EXCLUSIVO".', '[{"titulo":"Zapatillas","prompt":"Afiche de acción con unas zapatillas [color: blancas / rojas] sobre asfalto mojado y luz de neón. Título grande: \"SIN FRENOS\"."},{"titulo":"Skincare","prompt":"Afiche de ciencia ficción con un frasco de sérum flotando entre gotas de agua. Título grande: \"LA FÓRMULA\"."},{"titulo":"Café","prompt":"Afiche romántico con una bolsa de café artesanal al amanecer en una montaña. Título grande: \"PRIMER SORBO\"."}]'::jsonb, 'Tendencia: afiche de Hollywood de cosas cotidianas.', true, false, 103),
  ('producto-miniatura', 'Productos y anuncios', 'Tu producto gigante en miniatura', 'Obreros diminutos alrededor de tu producto: una foto que se recuerda.', '/showcase/idea-producto-miniatura.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía tilt-shift de una botella de perfume gigante de vidrio liso, sin etiqueta ni letras, rodeada de obreros diminutos con casco, andamios y una grúa pequeña, como si la estuvieran construyendo, foco selectivo, luz de estudio. Sin texto.', '[{"titulo":"Zapatilla","prompt":"Tilt-shift de una zapatilla de lona blanca gigante, lisa y sin logos ni franjas, con pintores diminutos en andamios dándole color [color: rojo / azul] con brochas, foco selectivo. Sin texto."},{"titulo":"Celular","prompt":"Tilt-shift de un celular gigante con limpiadores diminutos en andamios puliendo la pantalla, foco selectivo. Sin texto."},{"titulo":"Crema","prompt":"Tilt-shift de un frasco de crema gigante, blanco y liso sin etiqueta, con científicos diminutos de bata blanca, foco selectivo. Sin texto."}]'::jsonb, 'Tendencia: mundos en miniatura tilt-shift.', true, false, 104),
  ('depa-maqueta', 'Inmobiliaria', 'Tu proyecto como maqueta viva', 'Muestra un edificio o depa como maqueta tilt-shift: se entiende de un vistazo.', '/showcase/idea-depa-maqueta.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía tilt-shift de un edificio moderno de departamentos en una avenida arbolada de Lima visto como una maqueta en miniatura, autos y personas diminutas, foco selectivo, colores saturados, luz de mañana. Sin texto.', '[{"titulo":"Interior","prompt":"Maqueta tilt-shift de un departamento abierto sin techo, vista desde arriba, muebles diminutos de color [color: madera / blanco], foco selectivo. Sin texto."},{"titulo":"Casa de playa","prompt":"Maqueta tilt-shift de una casa de playa moderna con piscina, personas diminutas, foco selectivo. Sin texto."},{"titulo":"Condominio","prompt":"Maqueta tilt-shift de un condominio con áreas verdes y niños diminutos jugando, foco selectivo. Sin texto."}]'::jsonb, 'Tendencia: mundos en miniatura tilt-shift.', true, false, 105),
  ('ecom-fondo-blanco', 'Ecommerce y tiendas', 'Foto limpia para tu catálogo', 'Fondo blanco parejo, como exigen los marketplaces. Cambia el producto por el tuyo.', '/showcase/idea-ecom-fondo-blanco.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fotografía de catálogo de una licuadora de cocina con base de acero cepillado totalmente lisa, con una sola perilla redonda y sin ninguna marca, palabra ni letra, aislada sobre fondo blanco puro #FFFFFF, imagen de producto recortada y sin sombra, producto centrado y nítido, sin objetos alrededor. Sin texto.', '[{"titulo":"Zapatillas","prompt":"Fotografía de catálogo de unas zapatillas [color: blancas / negras] sobre fondo blanco puro, vista lateral, sombra suave, producto nítido. Sin texto."},{"titulo":"Bolso","prompt":"Fotografía de catálogo de un bolso de cuero marrón sobre fondo blanco puro, vista frontal, luz pareja, sombra suave. Sin texto."},{"titulo":"Perfume","prompt":"Fotografía de catálogo de un frasco de perfume de vidrio sobre fondo blanco puro, reflejo suave debajo, luz de estudio. Sin texto."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 106),
  ('ecom-empaquetando', 'Ecommerce y tiendas', 'Empacando pedidos en casa', 'Detrás de cámaras: mostrar los pedidos saliendo da confianza y prueba que vendes.', '/showcase/idea-ecom-empaquetando.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto casual sin producción de una emprendedora peruana de 30 años, mestiza, piel morena, rostro redondo y pelo negro recogido, con ropa común, empacando pedidos en la mesa de su sala sencilla, cajas de cartón, cinta y bolsas apiladas, ropa doblada, muebles viejos, luz natural de ventana, concentrada y sonriendo, piel real con poros. Sin texto ni logos.', '[{"titulo":"Solo manos","prompt":"Primer plano realista de manos cerrando una caja de cartón con cinta sobre una mesa, otras cajas apiladas detrás, luz natural. Sin texto ni logos."},{"titulo":"Hombre","prompt":"Foto casual sin producción de un emprendedor peruano de [edad: 25 / 40] años, mestizo de piel morena y pelo negro corto, con polo común, revisando pedidos en un pequeño depósito con estantes de metal y cajas sin etiquetas, luz fluorescente. Sin texto ni logos."},{"titulo":"Montaña de pedidos","prompt":"Foto casual sin producción de una pila grande de paquetes listos para enviar en la sala sencilla de una casa peruana, muebles viejos, una mujer mestiza de piel morena detrás celebrando. Sin texto ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 107),
  ('ecom-bolso-mercado', 'Ecommerce y tiendas', 'Tu bolso en la calle, con una modelo latina', 'Una persona real de tu país usando el producto vende más que el producto solo.', '/showcase/idea-ecom-bolso-mercado.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto casual sin producción de una mujer peruana de 32 años, mestiza, piel morena, rostro redondo y cabello negro, caminando por un mercado de flores de Lima con las manos libres y un bolso de cuero marrón al hombro, sonrisa natural, luz de mañana, piel real con poros sin retoque. Sin texto ni logos.', '[{"titulo":"Oficina","prompt":"Foto casual sin producción de una mujer peruana de [edad: 28 / 40] años, mestiza de piel morena, con ropa de oficina sencilla, entrando a un edificio de oficinas común de Lima con un bolso negro al hombro, luz natural, piel real con poros. Sin texto ni logos."},{"titulo":"Playa","prompt":"Foto casual sin producción de una mujer peruana mestiza de piel morena con vestido sencillo y bolso de paja en un malecón de Lima, baranda de concreto junto al mar, viento en el pelo, cielo gris, luz de tarde, piel real con poros. Sin texto ni logos."},{"titulo":"Mochila","prompt":"Foto casual sin producción de un joven peruano de piel morena con una sola mochila gris lisa en la espalda, esperando la combi en un paradero de una avenida de Lima, luz de mañana. Sin texto ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 108),
  ('ecom-envios', 'Ecommerce y tiendas', 'Anuncio de envíos a todo el país', 'Responde la pregunta que más te hacen antes de que te la hagan.', '/showcase/idea-ecom-envios.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Anuncio vertical con fondo azul intenso. Texto grande blanco arriba: "ENVÍOS A TODO EL PERÚ". En el centro, una caja de cartón lisa sin letras con una moto de reparto detrás. Abajo, en amarillo: "PAGAS AL RECIBIR".', '[{"titulo":"Colombia","prompt":"Anuncio vertical con fondo verde. Texto grande blanco: \"ENVÍOS A TODA COLOMBIA\". Una caja de cartón en el centro. Abajo en amarillo: \"PAGO CONTRA ENTREGA\"."},{"titulo":"México","prompt":"Anuncio vertical con fondo rojo. Texto grande blanco: \"ENVÍOS A TODO MÉXICO\". Una caja de cartón en el centro. Abajo en amarillo: \"RECIBE EN 3 DÍAS\"."},{"titulo":"Hoy mismo","prompt":"Anuncio vertical con fondo [color: negro / morado]. Texto grande blanco: \"ENTREGA HOY MISMO\". Una moto de reparto en el centro. Abajo en amarillo: \"EN LIMA\"."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 109),
  ('anime-retrato-personaje', 'Anime', 'Tu personaje de anime', 'Crea un protagonista propio con rasgos latinos y úsalo en toda la serie.', '/showcase/idea-anime-retrato-personaje.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Retrato de personaje de anime original, de medio cuerpo: una mujer latina adulta de 40 años, de rostro maduro con pómulos marcados, mandíbula definida y líneas de expresión junto a los ojos y la boca, piel morena, cabello negro ondulado y ojos cafés, con chaqueta de jean abotonada hasta el cuello que cubre todo el torso, sonrisa segura, fondo de colores suaves con luz de tarde, trazos limpios. Sin texto.', '[{"titulo":"Hombre","prompt":"Retrato de personaje de anime original, dibujo 2D con trazos limpios: un hombre latino adulto de 35 años de piel [tono: morena / trigueña], cabello negro rizado y polo blanco, mirada decidida, fondo liso. Sin texto."},{"titulo":"Villana","prompt":"Retrato de villana de anime original: mujer elegante de cabello plateado y ojos rojos, sonrisa fría, fondo oscuro con pétalos. Sin texto."},{"titulo":"Mascota","prompt":"Retrato de mascota de anime original, dibujo 2D con trazos limpios y colores planos: una cría de llama de cuello largo, orejas largas y lana blanca, tierna, con bufanda roja, ojos grandes, fondo pastel. Sin texto."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 110),
  ('anime-fondo-ciudad', 'Anime', 'Fondo de ciudad para tus escenas', 'Un fondo pintado a mano sin personajes, para narrar encima o poner subtítulos.', '/showcase/idea-anime-fondo-ciudad.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Fondo de anime pintado a mano sin personajes: una calle en pendiente de una ciudad latinoamericana al atardecer, casas de colores, cables de luz, un perro lejano, nubes grandes y luz dorada. Sin texto.', '[{"titulo":"De noche","prompt":"Fondo de anime sin personajes: una avenida vacía de noche, sin personas ni carros, con luces reflejadas en el piso mojado, sin letreros. Sin texto."},{"titulo":"Salón de clases","prompt":"Fondo de anime sin personajes: un salón de clases vacío con luz de tarde y pizarra en blanco. Sin texto."},{"titulo":"Montaña","prompt":"Fondo de anime sin personajes: un valle de los Andes con [clima: niebla / sol], casas pequeñas y nubes grandes. Sin texto."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 111),
  ('navidad-producto', 'Navidad y temporadas', 'Tu producto con ambiente navideño', 'Convierte la foto de tu producto en foto de campaña navideña sin alquilar estudio.', '/showcase/idea-navidad-producto.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto publicitaria realista de un frasco de perfume de vidrio sobre una mesa de madera con ramas de pino, luces cálidas desenfocadas y esferas doradas, ambiente navideño elegante. Sin texto ni logos.', '[{"titulo":"Zapatillas","prompt":"Foto publicitaria de unas zapatillas junto a un árbol de Navidad con luces cálidas desenfocadas y cajas de regalo. Sin texto ni logos."},{"titulo":"Comida","prompt":"Foto publicitaria de un panetón sobre una mesa navideña con taza de chocolate caliente, luces cálidas. Sin texto ni logos."},{"titulo":"Canasta","prompt":"Foto publicitaria de una canasta navideña con [producto: chocolates / vinos] y lazo rojo, fondo cálido. Sin texto ni logos."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 112),
  ('black-friday-afiche', 'Navidad y temporadas', 'Afiche de Black Friday', 'Precio grande y urgencia: se lee en un segundo y sirve para cualquier tienda.', '/showcase/idea-black-friday-afiche.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Afiche publicitario vertical con fondo negro y destellos dorados. Texto grande arriba: "BLACK FRIDAY". En el centro, unos audífonos negros y unas zapatillas de lona blancas y lisas, sin logos. Abajo, en amarillo: "50% OFF SOLO HOY".', '[{"titulo":"Moda","prompt":"Afiche con fondo negro. Texto grande: \"BLACK FRIDAY\". En el centro, un perchero con ropa. Abajo, en rojo: \"TODO A MITAD DE PRECIO\"."},{"titulo":"Tecnología","prompt":"Afiche con fondo azul oscuro. Texto grande: \"BLACK FRIDAY\". En el centro, un celular y una laptop. Abajo, en blanco: \"HASTA 40% OFF\"."},{"titulo":"Última hora","prompt":"Afiche con fondo [color: rojo / negro]. Texto grande: \"ÚLTIMAS HORAS\". En el centro, una caja de regalo. Abajo, en amarillo: \"NO TE LO PIERDAS\"."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 113),
  ('navidad-tarjeta', 'Navidad y temporadas', 'Tarjeta de saludo de tu negocio', 'Tu saludo navideño listo para WhatsApp, sin diseñador.', '/showcase/idea-navidad-tarjeta.jpg', null, 'image', 'qwen-image', '9:16', null, null, null, 'Tarjeta de saludo vertical con fondo rojo oscuro, ramas de pino y luces doradas en los bordes. Texto grande en blanco en el centro: "FELIZ NAVIDAD". Debajo, en dorado: "Gracias por confiar en nosotros".', '[{"titulo":"Año Nuevo","prompt":"Tarjeta vertical con fondo azul noche y fuegos artificiales dorados. Texto grande: \"FELIZ 2027\". Debajo: \"Vamos por más\"."},{"titulo":"Equipo","prompt":"Tarjeta vertical con fondo verde oscuro y luces doradas. Texto grande: \"FELICES FIESTAS\". Debajo: \"De parte de todo el equipo\"."},{"titulo":"Minimalista","prompt":"Tarjeta vertical con fondo [color: blanco / crema] y una rama de pino abajo. Arriba, texto grande en verde oscuro: \"FELIZ NAVIDAD\". Sin más adornos."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 114),
  ('gatito-travesura', 'Mascotas', 'Gatito saltando a la caja', 'Un gatito pequeño en pleno salto hacia su caja: la travesura que todos quieren volver a ver.', '/showcase/idea-gatito-travesura.jpg', null, 'image', 'z-image', '9:16', null, null, null, 'Foto realista de un gatito diminuto, bebé de cuatro semanas, con cabeza redonda grande y patitas cortas, en pleno salto, suspendido en el aire con las cuatro patitas estiradas, cayendo hacia una caja de cartón abierta mucho más grande que él. Sin texto ni logos.', '[{"titulo":"Con el papel","prompt":"Foto realista de un gatito atigrado diminuto, bebé de cuatro semanas, con cabeza redonda grande y patitas cortas, envuelto de pies a cabeza en tiras de papel higiénico, con el rollo desenrollado por el piso del baño y cara de inocente. Sin texto ni logos."},{"titulo":"Con la planta","prompt":"Foto realista de un gatito [color: naranja / gris] diminuto, bebé de cuatro semanas, con cabeza redonda grande y patitas cortas, sentado dentro de una maceta pequeña que le queda grande, con tierra en la nariz. Sin texto ni logos."},{"titulo":"Con el calcetín","prompt":"Foto realista de un gatito diminuto, bebé de tres semanas, de cara muy redonda, ojos grandes de cría y patitas cortas, arrastrando con la boca un calcetín más grande que él por el piso de la sala, con cara traviesa. Sin texto ni logos."}]'::jsonb, 'Pedido directo: gatitos pequeños haciendo cosas tiernas o graciosas. No sale de una tendencia medida.', true, false, 115),
  ('granja-unboxing', 'Tecnología y granjas', 'Abriendo la caja por primera vez', 'El momento en que se encienden todas las pantallas: un gancho de unboxing.', '/showcase/idea-granja-unboxing.jpg', '/showcase/idea-granja-unboxing.mp4', 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Dos manos abren una caja de metal negra sobre un escritorio de noche. Dentro se ven decenas de celulares en filas ordenadas, de pie, con la pantalla plana hacia la cámara, cada una encendida en color azul sólido y con un cable USB-C en el puerto inferior. Tapa vacía, sin logos ni íconos. Sonido de la tapa y zumbido suave y constante de ventiladores. Sin voz.', '[{"titulo":"Luz morada","prompt":"Manos abren una caja negra y los iPhones en filas se encienden con luz [color: morada / cian], de noche. Sin voz."},{"titulo":"Con voz","prompt":"Manos abren una caja llena de iPhones en filas y una voz masculina dice en español latino: \"Esto trabaja mientras duermes\"."},{"titulo":"Reacción","prompt":"Una persona joven abre una caja llena de iPhones encendidos y sonríe con la luz azul en la cara. Sin voz."}]'::jsonb, 'Refuerzo de Tecnología y granjas: primer plano, el punto fuerte del estilo.', true, false, 116),
  ('ecom-ugc-crema', 'Ecommerce y tiendas', 'Clienta recomendando tu crema', 'UGC con acento latino: una persona normal que parece clienta real.', '/showcase/idea-ecom-ugc-crema.jpg', '/showcase/idea-ecom-ugc-crema.mp4', 'video', 'ltx-25', '9:16', 8, '720p', 'fija', 'Una mujer latina de 34 años con polo gris de algodón, cabello recogido y sin maquillaje, en el baño de su casa, sostiene un pote de crema sin marca, mira a la cámara del celular y dice una sola vez con voz natural en español latino: "Llevo dos semanas usándola y mi piel cambió". Luz de ventana, cámara en mano, piel real. Sin subtítulos ni logos.', '[{"titulo":"Suplemento","prompt":"Un hombre latino de 40 años en su cocina sostiene un frasco y dice en español latino: \"Lo tomo cada mañana, y ya no me canso\". Cámara en mano. Sin subtítulos."},{"titulo":"Limpieza","prompt":"Una señora latina en su casa muestra un producto de limpieza y dice: \"Con esto se fue la mancha de [lugar: la cocina / el baño]\". Cámara en mano. Sin subtítulos."},{"titulo":"Café","prompt":"Una joven latina en su terraza toma café y dice: \"Este es el que pido cada mes\". Luz de mañana, cámara en mano. Sin subtítulos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 117),
  ('ecom-demo-licuadora', 'Ecommerce y tiendas', 'Demostración en 5 segundos', 'Muestra que funciona: el video de producto más directo para ecommerce.', '/showcase/idea-ecom-demo-licuadora.jpg', '/showcase/idea-ecom-demo-licuadora.mp4', 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Primer plano en una cocina latinoamericana: una mano enciende una licuadora y el mango se convierte en jugo en segundos, salpicaduras dentro del vaso. Sonido fuerte del motor y una voz dice en español latino: "Mira cómo queda". Luz natural. Sin subtítulos ni logos.', '[{"titulo":"Aspiradora","prompt":"Una aspiradora pequeña limpia migas de un sofá en una pasada, primer plano. Voz: \"Una pasada y listo\". Sin subtítulos ni logos."},{"titulo":"Plancha de pelo","prompt":"Una mano pasa una plancha por un mechón ondulado de cabello negro y queda lacio. Voz: \"Sin maltratar\". Sin subtítulos ni logos."},{"titulo":"Quitamanchas","prompt":"Una mano limpia una mancha de [mancha: café / vino] en una camisa blanca y desaparece. Voz: \"Así de fácil\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 118),
  ('ecom-prueba-ropa', 'Ecommerce y tiendas', 'Se prueba la prenda frente al espejo', 'Probarse la ropa en un cuarto real: el formato que más vende moda en redes.', '/showcase/idea-ecom-prueba-ropa.jpg', '/showcase/idea-ecom-prueba-ropa.mp4', 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Una joven latina de 25 años frente al espejo de su cuarto se mira con un vestido floral, gira y dice con voz alegre en español latino: "Me quedó perfecto, y es talla M". Cámara de celular, luz de tarde, cuarto ordenado y real. Sin subtítulos ni logos.', '[{"titulo":"Jean","prompt":"Una mujer latina de talla grande se prueba un jean frente al espejo y dice: \"Por fin uno que me queda bien\". Cámara de celular. Sin subtítulos ni logos."},{"titulo":"Zapatillas","prompt":"Un joven latino se sienta en su cama, se pone unas zapatillas y dice: \"Mira qué livianas\". Sin subtítulos ni logos."},{"titulo":"Conjunto","prompt":"Una mujer latina muestra un conjunto [estilo: deportivo / de oficina] frente al espejo y gira despacio. Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: ecommerce y realismo LATAM, no sale de una tendencia medida.', true, false, 119),
  ('anime-opening', 'Anime', 'Opening de tu propia serie', 'Unos segundos con energía de opening para presentar a tu personaje.', '/showcase/idea-anime-opening.jpg', '/showcase/idea-anime-opening.mp4', 'video', 'veo-fast', '9:16', 8, '720p', 'acercamiento', 'Animación anime original: un joven latino con chaqueta roja corre por una azotea de la ciudad al amanecer y salta hacia la cámara, el cielo se llena de luz dorada y pétalos. Música de rock enérgica instrumental. Sin voz, sin subtítulos ni texto.', '[{"titulo":"Grupo","prompt":"Animación anime original: cuatro amigos caminan hacia la cámara en una calle al atardecer con viento fuerte. Música de rock instrumental. Sin texto."},{"titulo":"Chica","prompt":"Animación anime original: una joven gira con su cabello al viento en un puente sobre un río de [ciudad: Arequipa / Medellín]. Sin texto."},{"titulo":"Fantasía","prompt":"Animación anime original: una viajera avanza por un valle con castillos flotantes y la cámara se eleva. Sin texto."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 120),
  ('anime-voz-latina', 'Anime', 'Escena de anime con voz en español', 'Diálogo corto con voz: se siente como un doblaje latino.', '/showcase/idea-anime-voz-latina.jpg', '/showcase/idea-anime-voz-latina.mp4', 'video', 'ltx-25', '9:16', 8, '720p', 'acercamiento', 'Animación anime original de drama: una joven de cabello negro corto en una estación de noche se voltea hacia la cámara con lágrimas y dice con voz quebrada en español latino: "Nunca me dijiste la verdad". Sonido de tren lejano. Sin subtítulos ni texto.', '[{"titulo":"Rival","prompt":"Animación anime original: un rival sonríe bajo la lluvia y dice en español latino: \"Esto recién empieza\". Sin subtítulos ni texto."},{"titulo":"Comedia","prompt":"Animación anime original: una estudiante grita en su cuarto en español latino: \"¡Otra vez me quedé dormida!\". Sin subtítulos ni texto."},{"titulo":"Mentor","prompt":"Animación anime original: un anciano sabio dice en español latino: \"La fuerza no está en tus puños\". Sin subtítulos ni texto."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 121),
  ('navidad-saludo-negocio', 'Navidad y temporadas', 'Saludo navideño de tu negocio', 'Una persona de tu equipo deseando felices fiestas: cercano y listo para enviar.', '/showcase/idea-navidad-saludo-negocio.jpg', '/showcase/idea-navidad-saludo-negocio.mp4', 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Una dueña de negocio latina de 40 años en su tienda decorada con luces de Navidad mira a la cámara y dice con voz cálida en español latino: "Gracias por acompañarnos este año. Feliz Navidad". Luz cálida, cámara en mano. Sin subtítulos ni logos.', '[{"titulo":"Equipo","prompt":"Un equipo de cinco personas latinas en su local dice a coro: \"¡Felices fiestas!\" con gorros navideños. Sin subtítulos ni logos."},{"titulo":"Restaurante","prompt":"Un chef latino en su restaurante decorado dice: \"Te esperamos esta Navidad\". Luz cálida. Sin subtítulos ni logos."},{"titulo":"Año Nuevo","prompt":"Una persona latina con fuegos artificiales detrás dice: \"Que este año venga con todo\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 122),
  ('black-friday-hook', 'Navidad y temporadas', 'Gancho de oferta de Black Friday', 'Una vendedora avisa la oferta con urgencia: directo para anuncios.', '/showcase/idea-black-friday-hook.jpg', '/showcase/idea-black-friday-hook.mp4', 'video', 'ltx-25', '9:16', 5, '720p', 'fija', 'Una vendedora latina de 28 años en su tienda de ropa mira a la cámara con emoción y dice en español latino: "Solo por hoy, todo a mitad de precio. Corre". Percheros detrás, cámara en mano, luz de tienda. Sin subtítulos ni logos.', '[{"titulo":"Tecnología","prompt":"Un vendedor latino en una tienda de celulares dice: \"Este precio no vuelve hasta el otro año\". Sin subtítulos ni logos."},{"titulo":"Última hora","prompt":"Una emprendedora latina en su casa con cajas detrás dice: \"Me quedan [cantidad: diez / cinco], escríbeme ahora\". Sin subtítulos ni logos."},{"titulo":"Comida","prompt":"Un dueño de restaurante latino dice: \"Hoy, dos por uno en todo el menú\". Sin subtítulos ni logos."}]'::jsonb, 'Pedido del gerente: categoría nueva, no sale de una tendencia medida.', true, false, 123),
  ('gatito-bosteza', 'Mascotas', 'Gatito que se despierta', 'Cinco segundos de ternura: bostezo, estirón y mirada a cámara.', '/showcase/idea-gatito-bosteza.jpg', '/showcase/idea-gatito-bosteza.mp4', 'video', 'ltx-25', '9:16', 5, '720p', 'acercamiento', 'Primer plano realista de un gatito atigrado diminuto, cría de pocas semanas, dormido sobre una manta, que despierta, bosteza, estira las patitas y mira a la cámara con ojos enormes. Maullido muy agudo, luz de mañana, la cámara se acerca despacio. Sin voz, sin texto ni logos.', '[{"titulo":"Se cae jugando","prompt":"Un gatito blanco diminuto intenta atrapar un hilo de lana y se cae de lado sobre una manta, luego se levanta. Maullido agudo. Sin texto ni logos."},{"titulo":"Da pasitos","prompt":"Un gatito diminuto camina con pasitos torpes hacia la cámara sobre una alfombra y se tropieza. Maullido agudo. Sin texto ni logos."},{"titulo":"Mira la lluvia","prompt":"Un gatito [color: naranja / gris] diminuto toca con la patita las gotas de una ventana y voltea a la cámara. Sonido de lluvia. Sin texto ni logos."}]'::jsonb, 'Pedido directo: gatitos pequeños haciendo cosas tiernas o graciosas. No sale de una tendencia medida.', true, false, 124)
